// Non-resource secret names. Resource bindings are generated by wrangler types.
interface Env {
  WORLD_ID_CLIENT_ID: string;
  WORLD_ID_CLIENT_SECRET: string;
  WORLD_ID_CLIENT_AUTH: 'client_secret_basic' | 'client_secret_post';
  STATE_KEY: string;
  ATTESTATION_PRIVATE_JWK: string;
  ATTESTATION_PUBLIC_JWK: string;
  SPONSOR_PRIVATE_KEY: `0x${string}`;
}
